head.script:
//
    tailwind.config = {
        theme: {
            extend: {
                fontFamily: { sans: ['"Plus Jakarta Sans"', 'sans-serif'] },
                colors: {
                    primary: '#FF4757',
                    secondary: '#2ED573',
                    tertiary: '#1E90FF',
                    dark: '#2F3542',
                    light: '#F1F2F6',
                    surface: '#FFFFFF'
                },
                boxShadow: {
                    'soft': '0 4px 20px -2px rgba(0, 0, 0, 0.05)',
                    'glow': '0 4px 15px rgba(255, 71, 87, 0.3)'
                }
            }
        }
    }
//

head.b:skin:
/* Base Configuration */
body {
    background-color: #e4e9f2;
    font-family: 'Plus Jakarta Sans', sans-serif;
    -webkit-tap-highlight-color: transparent;
    margin: 0;
    padding: 0;
}

/* Mobile Layout Standard */
.mobile-container {
    max-width: 414px;
    margin: 0 auto;
    background-color: #F8F9FA;
    height: 100vh;
    position: relative;
    box-shadow: 0 10px 30px rgba(0,0,0,0.2);
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

.scrollable-content {
    flex: 1;
    overflow-y: auto;
    padding-bottom: 110px;
    scroll-behavior: smooth;
    -webkit-overflow-scrolling: touch;
}
.scrollable-content::-webkit-scrollbar { display: none; }
.scrollable-content { -ms-overflow-style: none; scrollbar-width: none; }

/* Navigation Standards */
.bottom-nav {
    position: absolute;
    bottom: 0;
    width: 100%;
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(15px);
    border-top: 1px solid rgba(0,0,0,0.05);
    display: flex;
    justify-content: space-around;
    padding: 12px 0 calc(12px + env(safe-area-inset-bottom));
    z-index: 40;
    border-radius: 30px 30px 0 0;
    box-shadow: 0 -5px 20px rgba(0,0,0,0.03);
}
.nav-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    color: #A4B0BE;
    font-size: 0.65rem;
    font-weight: 700;
    transition: all 0.3s ease;
    cursor: pointer;
    width: 25%;
    gap: 4px;
}
.nav-item i { font-size: 1.3rem; transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1); }
.nav-item.active { color: #FF4757; }
.nav-item.active i { transform: translateY(-4px) scale(1.15); text-shadow: 0 4px 10px rgba(255,71,87,0.3); }

/* View Transitions */
.screen { display: none; height: 100%; flex-direction: column; }
.screen.active { display: flex; animation: fadeIn 0.4s ease-out; }
@keyframes fadeIn { from { opacity: 0; transform: scale(0.98); } to { opacity: 1; transform: scale(1); } }

/* Modal Architectures */
.modal-overlay {
    position: absolute; top: 0; left: 0; width: 100%; height: 100%;
    background: rgba(47, 53, 66, 0.6); z-index: 50;
    display: none; justify-content: center; align-items: flex-end;
    backdrop-filter: blur(5px);
    opacity: 0; transition: opacity 0.3s ease;
}
.modal-overlay.active { display: flex; opacity: 1; }

.modal-content {
    background: #FFFFFF; width: 100%; max-height: 92%;
    border-radius: 32px 32px 0 0; padding: 24px;
    overflow-y: auto; transform: translateY(100%);
    transition: transform 0.4s cubic-bezier(0.2, 0.8, 0.2, 1);
    box-shadow: 0 -10px 40px rgba(0,0,0,0.1);
    display: flex; flex-direction: column;
}
.modal-overlay.active .modal-content { transform: translateY(0); }
.modal-content::-webkit-scrollbar { display: none; }

/* Centered Pop-up Modal */
.modal-overlay.centered {
    align-items: center;
    justify-content: center;
    padding: 1.5rem;
}
.modal-overlay.centered .modal-content {
    border-radius: 32px; width: 100%; max-width: 340px;
    transform: scale(0.9); opacity: 0; padding: 24px;
    transition: all 0.3s cubic-bezier(0.2, 0.8, 0.2, 1);
    max-height: 85vh; margin: 0;
}
.modal-overlay.centered.active .modal-content { transform: scale(1); opacity: 1; }

/* UI Components Standard */
#toast-container {
    position: absolute; top: 20px; left: 0; right: 0;
    display: flex; flex-direction: column; align-items: center; gap: 10px;
    z-index: 100; pointer-events: none;
}
.toast {
    background: #2F3542; color: white; padding: 14px 24px;
    border-radius: 100px; font-size: 0.85rem; font-weight: 600;
    box-shadow: 0 10px 25px -5px rgba(0,0,0,0.2);
    animation: slideDown 0.4s cubic-bezier(0.2, 0.8, 0.2, 1);
    pointer-events: auto; max-width: 90%; text-align: center;
    display: flex; align-items: center; gap: 8px;
}
.toast.error { background: #FF4757; }
.toast.success { background: #2ED573; }
.toast.info { background: #1E90FF; }
@keyframes slideDown { from { opacity: 0; transform: translateY(-30px); } to { opacity: 1; transform: translateY(0); } }

/* Global Loader */
#global-loader {
    position: absolute; top: 0; left: 0; width: 100%; height: 100%;
    background: rgba(255,255,255,0.85); backdrop-filter: blur(3px);
    z-index: 999; display: flex; flex-direction: column;
    align-items: center; justify-content: center;
    opacity: 0; pointer-events: none; transition: opacity 0.3s ease;
}
#global-loader.active { opacity: 1; pointer-events: auto; }
.spinner {
    width: 50px; height: 50px;
    border: 4px solid #F1F2F6; border-top-color: #FF4757;
    border-radius: 50%; animation: spin 1s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

.input-modern {
    width: 100%; background: #F1F2F6; border: 1.5px solid transparent;
    border-radius: 16px; padding: 14px 16px; font-size: 0.9rem; font-weight: 600;
    color: #2F3542; transition: all 0.3s ease;
}
.input-modern:focus { background: #FFFFFF; border-color: #FF4757; outline: none; box-shadow: 0 0 0 4px rgba(255,71,87,0.1); }
.input-modern::placeholder { color: #A4B0BE; font-weight: 500; }
.input-modern:disabled, .input-modern[readonly] { background: #E5E7EB; cursor: not-allowed; opacity: 0.7; }

.label-modern { display: block; font-size: 0.7rem; font-weight: 800; color: #747D8C; margin-bottom: 6px; text-transform: uppercase; letter-spacing: 0.5px; }

.star-rating i { color: #E5E7EB; cursor: pointer; transition: all 0.2s; }
.star-rating i:active { transform: scale(0.8); }
.star-rating i.active { color: #FFA502; text-shadow: 0 2px 10px rgba(255, 165, 2, 0.3); }

.scanner-line { animation: scan 2s cubic-bezier(0.4, 0, 0.2, 1) infinite; }
@keyframes scan { 0% { transform: translateY(0); } 50% { transform: translateY(220px); } 100% { transform: translateY(0); } }

body.script:
//
    /**
     * @module AppConfig
     */
    const APP_CONFIG = {
        // TODO: PASTE URL GOOGLE APPS SCRIPT WEB APP DI BAWAH INI
        API_URL: 'https://script.google.com/macros/s/AKfycbytMJxT6KZfVs0G_Kp4ely0mdVjuKIr-u3EeNfT5WSOB6o0nFGo3zRSC1qqil4XssXF/exec'
    };

    /**
     * @module State
     */
    const STATE = {
        currentUser: null,
        activeEventId: null,
        activeGalleryEventId: null,
        activeReportEventId: null,
        tempAvatarData: null,
        checkout: { qty: 1, discount: 0, basePrice: 0 },
        formBuilderFields: [],
        favorites: [],
        db: {
            events: [], categories: [], formTemplates: [], payments: [],
            vouchers: [], galleries: [],
            users: [], tickets: [], orders: [], reviews: [], formResponses: [], settings: [], auditLogs: []
        }
    };

    /**
     * @module UIHelper
     */
    const UIHelper = {
        showLoader() { document.getElementById('global-loader').classList.add('active'); },
        hideLoader() { document.getElementById('global-loader').classList.remove('active'); },
        showToast(msg, type = 'success') {
            try {
                const container = document.getElementById('toast-container');
                const toast = document.createElement('div');
                toast.className = `toast ${type}`;
                let icon = type === 'success' ? 'fa-check-circle' : (type === 'error' ? 'fa-exclamation-circle' : 'fa-info-circle');
                toast.innerHTML = `<i class="fas ${icon} text-lg"></i> ${msg}`;
                container.appendChild(toast);
                setTimeout(() => {
                    toast.style.opacity = '0';
                    setTimeout(() => toast.remove(), 400);
                }, 3000);
            } catch (err) { console.error('Toast Error:', err); }
        },
        formatRupiah(amount) {
            if(amount === 0) return 'GRATIS';
            return new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(amount);
        },
        formatDate(dateStr) {
            const opts = { weekday:'long', day: 'numeric', month: 'long', year: 'numeric', hour:'2-digit', minute:'2-digit' };
            return new Date(dateStr).toLocaleDateString('id-ID', opts).replace(' pukul', ' •');
        },
        getInitials(name) {
            if(!name) return 'AN';
            return name.split(' ').map(n=>n[0]).join('').substring(0,2).toUpperCase();
        },
        formatPhone(phone) {
            if (phone.startsWith('0')) return '62' + phone.substring(1);
            return phone;
        },
        switchTab(role, tabName, element) {
            try {
                const navItems = element.parentElement.querySelectorAll('.nav-item');
                navItems.forEach(n => n.classList.remove('active'));
                element.classList.add('active');

                const screen = document.getElementById(`screen-${role}`);
                if (!screen) return;

                const views = screen.querySelectorAll('.active-view');
                views.forEach(v => v.classList.add('hidden'));

                const prefixMap = { 'admin': 'admin', 'customer': 'cust', 'instructor': 'ins' };
                const prefix = prefixMap[role] || role;
                const targetView = document.getElementById(`${prefix}-view-${tabName}`);

                if (targetView) targetView.classList.remove('hidden');
            } catch (e) { console.error('UI Navigation Error:', e); }
        },
        openModal(id) {
            const modal = document.getElementById(id);
            if (modal) modal.classList.add('active');
        },
        closeModal(event, id, force = false) {
            try {
                if (force || (event && event.target.id === id)) {
                    const modal = document.getElementById(id);
                    if (modal) modal.classList.remove('active');
                }
            } catch (e) { console.error('Modal Closing Error:', e); }
        },
        showConfirm(title, message, onConfirm) {
            try {
                document.getElementById('confirm-title').innerText = title;
                document.getElementById('confirm-msg').innerText = message;

                const btnYes = document.getElementById('confirm-btn-yes');
                const newBtnYes = btnYes.cloneNode(true);
                btnYes.parentNode.replaceChild(newBtnYes, btnYes);

                newBtnYes.addEventListener('click', () => {
                    this.closeModal(null, 'modal-confirm', true);
                    if (typeof onConfirm === 'function') onConfirm();
                });
                this.openModal('modal-confirm');
            } catch (e) { console.error('Confirm Error:', e); }
        },
        copyToClipboard(text) {
            try {
                const el = document.createElement('textarea');
                el.value = text;
                document.body.appendChild(el);
                el.select();
                document.execCommand('copy');
                document.body.removeChild(el);
                this.showToast('Tautan/Data disalin!', 'info');
            } catch (e) { this.showToast('Gagal menyalin', 'error'); }
        }
    };

    /**
     * @module ApiService
     */
    const ApiService = {
        async call(action, payload = {}) {
            UIHelper.showLoader();
            try {
                const response = await fetch(APP_CONFIG.API_URL, {
                    method: 'POST',
                    headers: { 'Content-Type': 'text/plain' }, // Bypass CORS via text/plain
                    body: JSON.stringify({ action, payload })
                });

                const result = await response.json();
                if (!result.success) throw new Error(result.message);
                return result;
            } catch (error) {
                console.error(`API Error [${action}]:`, error);
                throw error;
            } finally {
                UIHelper.hideLoader();
            }
        },

        async initData() {
            const res = await this.call('INIT_DATA');
            Object.assign(STATE.db, res.data);
        },

        async syncSession() {
            if(!STATE.currentUser) return;
            const res = await this.call('SYNC_SESSION', { phone: STATE.currentUser.Phone, role: STATE.currentUser.Role });
            Object.assign(STATE.db, res.data);
        }
    };

    /**
     * @module AuthController
     */
    const AuthController = {
        toggleAuthMode(mode) {
            if(mode === 'register') {
                document.getElementById('auth-login-section').classList.add('hidden');
                document.getElementById('auth-register-section').classList.remove('hidden');
            } else {
                document.getElementById('auth-register-section').classList.add('hidden');
                document.getElementById('auth-login-section').classList.remove('hidden');
            }
        },
        async handleLogin() {
            try {
                const phone = document.getElementById('login-id').value.trim();
                const pass = document.getElementById('login-pass').value;
                if(!phone || !pass) throw new Error("ID dan Kata sandi wajib diisi");

                const res = await ApiService.call('LOGIN', { phone, pass });
                await this.performLogin(res.data);
            } catch (error) { UIHelper.showToast(error.message, 'error'); }
        },
        async handleRegister() {
            try {
                const name = document.getElementById('reg-name').value.trim();
                const phone = document.getElementById('reg-phone').value.trim();
                const city = document.getElementById('reg-city').value.trim();
                const pass = document.getElementById('reg-pass').value;

                if(!name || !phone || !city || !pass) throw new Error("Semua field wajib diisi");
                const res = await ApiService.call('REGISTER', { name, phone, city, pass });

                UIHelper.showToast(res.message);
                this.toggleAuthMode('login');
                document.getElementById('login-id').value = phone;
                document.getElementById('login-pass').value = pass;
            } catch (error) { UIHelper.showToast(error.message, 'error'); }
        },
        async quickLogin(role) {
            try {
                let phone = role === 'admin' ? 'admin' : (role === 'instructor' ? '08999999999' : '08123456789');
                const res = await ApiService.call('LOGIN', { phone, pass: 'demo' });
                await this.performLogin(res.data);
            } catch(e) { UIHelper.showToast(e.message, 'error'); }
        },
        async performLogin(user) {
            STATE.currentUser = user;
            await ApiService.syncSession();

            document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
            document.getElementById(`screen-${user.Role}`).classList.add('active');

            if(user.Role === 'admin') AdminController.init();
            if(user.Role === 'customer') CustomerController.init();
            if(user.Role === 'instructor') InstructorController.init();

            UIHelper.showToast(`Autentikasi berhasil, Halo ${user.Name.split(' ')[0]}!`);
        },
        logout() {
            UIHelper.showConfirm("Keluar Sistem", "Anda yakin ingin keluar dari akun ini?", () => {
                STATE.currentUser = null;
                document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
                document.getElementById('screen-auth').classList.add('active');
                document.getElementById('login-id').value = ''; document.getElementById('login-pass').value = '';
            });
        },
        openEditProfile() {
            const user = STATE.currentUser;
            document.getElementById('edit-profile-name').value = user.Name;
            document.getElementById('edit-profile-phone').value = user.Phone;
            document.getElementById('edit-profile-pass').value = '';

            const cityWrapper = document.getElementById('edit-profile-city-wrapper');
            if (user.Role === 'customer') {
                cityWrapper.classList.remove('hidden');
                document.getElementById('edit-profile-city').value = user.City || '';
            } else {
                cityWrapper.classList.add('hidden');
            }

            const preview = document.getElementById('edit-profile-avatar-preview');
            const icon = document.getElementById('edit-profile-avatar-icon');
            STATE.tempAvatarData = null;
            if (user.Avatar) {
                preview.src = user.Avatar; preview.classList.remove('hidden'); icon.classList.add('hidden');
            } else {
                preview.src = ''; preview.classList.add('hidden'); icon.classList.remove('hidden');
            }
            UIHelper.openModal('modal-edit-profile');
        },
        previewAvatar(event) {
            const file = event.target.files[0];
            if (!file) return;
            if (file.size > 2 * 1024 * 1024) return UIHelper.showToast("Maksimal ukuran foto 2MB", "error");
            const reader = new FileReader();
            reader.onload = (e) => {
                STATE.tempAvatarData = e.target.result;
                const preview = document.getElementById('edit-profile-avatar-preview');
                preview.src = e.target.result; preview.classList.remove('hidden');
                document.getElementById('edit-profile-avatar-icon').classList.add('hidden');
            };
            reader.readAsDataURL(file);
        },
        async previewAvatarAndSave(event) {
             const file = event.target.files[0];
             if (!file) return;
             if (file.size > 2 * 1024 * 1024) return UIHelper.showToast("Maksimal ukuran foto 2MB", "error");

             UIHelper.showLoader();
             const reader = new FileReader();
             reader.onload = async (e) => {
                 try {
                     const res = await ApiService.call('SAVE_PROFILE', { phone: STATE.currentUser.Phone, name: STATE.currentUser.Name, avatar: e.target.result });
                     STATE.currentUser = res.data;
                     CustomerController.updateProfileUI(res.data);
                     UIHelper.showToast('Foto profil diunggah!');
                 } catch(err) {
                     UIHelper.showToast(err.message, 'error');
                 } finally {
                     UIHelper.hideLoader();
                 }
             };
             reader.readAsDataURL(file);
        },
        async saveProfile() {
            try {
                const name = document.getElementById('edit-profile-name').value.trim();
                const pass = document.getElementById('edit-profile-pass').value;
                if(!name) throw new Error('Nama tidak boleh kosong');

                const payload = { phone: STATE.currentUser.Phone, name };
                if (STATE.currentUser.Role === 'customer') payload.city = document.getElementById('edit-profile-city').value.trim();
                if (pass) {
                    if(pass.length < 6) throw new Error("Kata sandi minimal 6 karakter");
                    payload.pass = pass;
                }
                if (STATE.tempAvatarData) payload.avatar = STATE.tempAvatarData;

                const res = await ApiService.call('SAVE_PROFILE', payload);
                STATE.currentUser = res.data;

                UIHelper.showToast('Profil diperbarui');
                UIHelper.closeModal(null, 'modal-edit-profile', true);

                if(res.data.Role === 'customer') CustomerController.updateProfileUI(res.data);
                else if (res.data.Role === 'instructor') document.getElementById('instructor-name-display').innerText = name;
            } catch (e) { UIHelper.showToast(e.message, 'error'); }
        }
    };

    /**
     * @module CustomerController
     */
    const CustomerController = {
        init() {
            const user = STATE.currentUser;
            this.updateProfileUI(user);
            document.getElementById('profile-phone').innerText = user.Phone;

            document.querySelectorAll('#screen-customer .bottom-nav .nav-item')[0].click();
            this.renderEvents();
            this.renderTickets('active');
        },
        updateProfileUI(user) {
            document.getElementById('customer-name-display').innerText = user.Name;
            document.getElementById('profile-name').innerText = user.Name;
            document.getElementById('profile-city').innerHTML = `<i class="fas fa-map-marker-alt"></i> ${user.City || 'Belum diatur'}`;

            const avatarHtml = user.Avatar
                ? `<img src="${user.Avatar}" class="w-full h-full rounded-full object-cover">`
                : UIHelper.getInitials(user.Name);
            document.getElementById('customer-avatar-initial').innerHTML = avatarHtml;
            document.getElementById('profile-avatar-initial').innerHTML = avatarHtml;
        },
        filterEvents() {
            const q = document.getElementById('search-event-input').value.toLowerCase().trim();
            this.renderEvents(q);
        },
        renderEvents(query = '') {
            try {
                const container = document.getElementById('cust-event-list');
                const titleEl = document.getElementById('cust-discovery-title');
                container.innerHTML = '';

                const userCity = STATE.currentUser.City ? STATE.currentUser.City.toLowerCase() : '';

                if (query !== '') {
                    titleEl.innerText = 'Hasil Pencarian';
                } else {
                    titleEl.innerText = `Event di ${STATE.currentUser.City || 'Kota Anda'}`;
                }

                const filtered = STATE.db.events.filter(e => {
                    const isMatch = String(e.Title).toLowerCase().includes(query) || String(e.Instructor).toLowerCase().includes(query) || String(e.City).toLowerCase().includes(query);
                    const isExactSlug = query && String(e.Slug).toLowerCase() === query;
                    const matchesCity = String(e.City).toLowerCase() === userCity;

                    if (e.Visibility === 'public') {
                        if(query === '') return matchesCity;
                        return isMatch;
                    }
                    if (e.Visibility === 'hidden') return isExactSlug;
                    return false;
                });

                if(filtered.length === 0) {
                    container.innerHTML = '<div class="text-center p-8 bg-white rounded-3xl shadow-sm border border-gray-100"><i class="fas fa-search-location text-4xl text-gray-200 mb-3 block"></i><p class="text-gray-400 text-sm font-semibold">Tidak ada event yang ditemukan.</p></div>';
                    return;
                }

                filtered.forEach(event => {
                    const isFav = STATE.favorites.includes(event.ID);
                    const d = new Date(event.Date);

                    const html = `
                        <div class="bg-white rounded-3xl shadow-soft overflow-hidden active:scale-[0.98] transition-transform cursor-pointer group border border-gray-50" onclick="CustomerController.openEventDetail('${event.ID}')">
                            <div class="h-44 bg-gray-200 relative overflow-hidden">
                                <img src="${event.Banner}" class="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" onerror="this.src='https://placehold.co/600x400/F1F2F6/2F3542?text=Banner'">
                                <div class="absolute top-4 right-4 bg-white/90 backdrop-blur px-3.5 py-1.5 rounded-xl text-xs font-extrabold text-primary shadow-sm">
                                    ${UIHelper.formatRupiah(event.Price)}
                                </div>
                                <div class="absolute bottom-4 left-4 flex gap-2">
                                    <span class="text-[10px] bg-dark text-white px-2.5 py-1 rounded-lg uppercase font-extrabold tracking-wider shadow-sm">${event.Category}</span>
                                </div>
                                ${isFav ? `<div class="absolute top-4 left-4 text-primary"><i class="fas fa-heart text-2xl drop-shadow-md"></i></div>` : ''}
                            </div>
                            <div class="p-5 relative">
                                <div class="absolute -top-6 right-5 w-12 h-12 bg-white rounded-2xl shadow-soft flex flex-col items-center justify-center text-primary border border-gray-50">
                                    <span class="text-sm font-extrabold leading-none">${d.getDate()}</span>
                                    <span class="text-[9px] uppercase font-bold tracking-widest leading-none mt-0.5">${d.toLocaleString('id-ID',{month:'short'})}</span>
                                </div>
                                <h4 class="font-extrabold text-dark leading-tight mb-2 text-lg pr-14">${event.Title}</h4>
                                <div class="flex items-center text-xs text-gray-500 font-semibold gap-4">
                                    <span><i class="fas fa-map-marker-alt mr-1 text-gray-400"></i> ${event.City}</span>
                                    <span><i class="fas fa-user-ninja mr-1 text-gray-400"></i> ${event.Instructor}</span>
                                </div>
                            </div>
                        </div>
                    `;
                    container.innerHTML += html;
                });
            } catch (e) { console.error('Render Events Error', e); }
        },
        openEventDetail(id) {
            try {
                const event = STATE.db.events.find(e => e.ID === id);
                if(!event) return;
                STATE.activeEventId = id;
                const isFav = STATE.favorites.includes(id);

                document.getElementById('detail-img').src = event.Banner;
                document.getElementById('detail-title').innerText = event.Title;
                document.getElementById('detail-category').innerText = event.Category;
                document.getElementById('detail-price').innerText = UIHelper.formatRupiah(event.Price);
                document.getElementById('detail-date').innerText = UIHelper.formatDate(event.Date);
                document.getElementById('detail-city').innerText = event.City;
                document.getElementById('detail-instructor').innerText = event.Instructor;
                document.getElementById('detail-instructor-info').innerText = event.InstructorInfo || '-';
                document.getElementById('detail-desc').innerText = event.Desc;
                document.getElementById('detail-venue').innerText = event.Venue;
                document.getElementById('detail-address').innerText = event.Address;
                document.getElementById('detail-capacity').innerText = event.Capacity;

                const gmaps = document.getElementById('detail-gmaps');
                if(event.Gmaps) { gmaps.style.display = 'flex'; gmaps.href = event.Gmaps; }
                else gmaps.style.display = 'none';

                document.getElementById('btn-favorite').className = isFav ? "text-primary transition-colors p-1" : "text-gray-300 hover:text-primary transition-colors p-1";
                UIHelper.openModal('modal-event-detail');
            } catch (e) {}
        },
        toggleFavorite() {
            const id = STATE.activeEventId;
            const idx = STATE.favorites.indexOf(id);
            if(idx > -1) STATE.favorites.splice(idx, 1);
            else STATE.favorites.push(id);
            this.openEventDetail(id);
            this.renderEvents();
            UIHelper.showToast(idx > -1 ? 'Dihapus dari favorit' : 'Disimpan ke favorit');
        },
        shareEventWA() {
            const event = STATE.db.events.find(e => e.ID === STATE.activeEventId);
            const link = `https://activenation.id/e/${event.Slug}`;
            const text = encodeURIComponent(`Yuk ikutan event *${event.Title}* di ${event.City}!\n\n📅 ${UIHelper.formatDate(event.Date)}\n📍 ${event.Venue}\n\nAmankan tiketmu sekarang: ${link}`);
            window.open(`https://wa.me/?text=${text}`, '_blank');
        },
        openCheckout() {
            const event = STATE.db.events.find(e => e.ID === STATE.activeEventId);
            STATE.checkout = { qty: 1, basePrice: event.Price, discount: 0 };

            UIHelper.closeModal(null, 'modal-event-detail', true);
            document.getElementById('checkout-title').innerText = event.Title;
            document.getElementById('voucher-code').value = '';
            document.getElementById('transfer-proof').value = '';

            const activePayments = STATE.db.payments.filter(p => p.IsActive);
            const paySelect = document.getElementById('checkout-payment-select');
            paySelect.innerHTML = activePayments.map(p => `<option value="${p.ID}">${p.Name} (${p.Type.toUpperCase()})</option>`).join('');

            this.changePaymentMethod();
            this.updateCheckoutUI();
            UIHelper.openModal('modal-checkout');
        },
        changePaymentMethod() {
            const selId = document.getElementById('checkout-payment-select').value;
            const p = STATE.db.payments.find(x => x.ID === selId);
            if(!p) return;

            const qrisCon = document.getElementById('checkout-qris-container');
            const tfCon = document.getElementById('checkout-transfer-container');

            if (p.Type === 'qris') {
                qrisCon.classList.remove('hidden');
                tfCon.classList.add('hidden');
                document.getElementById('checkout-qris-img').src = p.QrUrl || 'https://placehold.co/400x400/F1F2F6/FF4757?text=Invalid';
            } else {
                qrisCon.classList.add('hidden');
                tfCon.classList.remove('hidden');
                document.getElementById('checkout-bank-name').innerText = p.Name;
                document.getElementById('checkout-acc-no').innerText = p.AccountNo;
                document.getElementById('checkout-acc-name').innerText = p.AccountName;
            }
        },
        updateQty(delta) {
            let newQty = STATE.checkout.qty + delta;
            if(newQty < 1) newQty = 1;
            if(newQty > 5) return UIHelper.showToast('Maksimal 5 tiket','error');
            STATE.checkout.qty = newQty;
            this.updateCheckoutUI();
        },
        applyVoucher() {
            try {
                const code = document.getElementById('voucher-code').value.toUpperCase().trim();
                if(STATE.checkout.basePrice === 0) throw new Error("Event gratis.");
                if(code === "") throw new Error("Masukkan kode.");

                const voucher = STATE.db.vouchers.find(v => v.Code === code);
                if(voucher) {
                    let discount = voucher.Type === 'percent' ? (STATE.checkout.basePrice * voucher.Val / 100) : voucher.Val;
                    if(discount > STATE.checkout.basePrice) discount = STATE.checkout.basePrice;
                    STATE.checkout.discount = discount;
                    UIHelper.showToast("Voucher diterapkan!");
                    this.updateCheckoutUI();
                } else {
                    STATE.checkout.discount = 0;
                    this.updateCheckoutUI();
                    throw new Error("Kode tidak valid.");
                }
            } catch (err) { UIHelper.showToast(err.message, "error"); }
        },
        updateCheckoutUI() {
            document.getElementById('checkout-qty').innerText = STATE.checkout.qty;
            const subtotal = STATE.checkout.basePrice * STATE.checkout.qty;
            const totalDisc = STATE.checkout.discount * STATE.checkout.qty;
            const finalPrice = subtotal - totalDisc;

            document.getElementById('checkout-price').innerText = UIHelper.formatRupiah(finalPrice);

            const discInfo = document.getElementById('checkout-discount-info');
            if(totalDisc > 0) {
                discInfo.classList.remove('hidden'); discInfo.innerText = `Hemat ${UIHelper.formatRupiah(totalDisc)}`;
            } else { discInfo.classList.add('hidden'); }

            document.getElementById('payment-section').style.display = finalPrice === 0 ? 'none' : 'block';
        },
        async processCheckout() {
            try {
                const finalPrice = (STATE.checkout.basePrice - STATE.checkout.discount) * STATE.checkout.qty;
                if (finalPrice > 0) {
                    const activeP = STATE.db.payments.filter(p=>p.IsActive).length > 0;
                    if(!activeP) throw new Error("Metode pembayaran belum tersedia. Hubungi Admin.");
                    const proof = document.getElementById('transfer-proof').files[0];
                    if(!proof) throw new Error("Wajib mengunggah bukti transfer!");
                }

                const res = await ApiService.call('CREATE_ORDER', {
                    eventId: STATE.activeEventId, customerPhone: STATE.currentUser.Phone,
                    finalPrice: finalPrice, qty: STATE.checkout.qty
                });

                UIHelper.closeModal(null, 'modal-checkout', true);
                UIHelper.showToast(res.message);

                await ApiService.syncSession();

                if (!res.data.requiresPayment) {
                    document.getElementById('tab-ticket-active').click();
                    document.querySelectorAll('#screen-customer .bottom-nav .nav-item')[1].click();
                }
            } catch (err) { UIHelper.showToast(err.message, "error"); }
        },
        toggleTicketTab(tab) {
            const actCls = 'flex-1 py-2.5 bg-white rounded-xl font-bold text-xs shadow-sm text-primary transition-all';
            const inactCls = 'flex-1 py-2.5 text-gray-500 font-bold text-xs transition-all bg-transparent hover:bg-white/50 rounded-xl';
            document.getElementById('tab-ticket-active').className = tab === 'active' ? actCls : inactCls;
            document.getElementById('tab-ticket-history').className = tab === 'attended' ? actCls : inactCls;
            this.renderTickets(tab);
        },
        renderTickets(status) {
            try {
                const container = document.getElementById('cust-ticket-list');
                container.innerHTML = '';
                const myTickets = STATE.db.tickets.filter(t => t.Status === status);

                if(myTickets.length === 0) {
                    container.innerHTML = `<div class="text-center p-10 bg-white rounded-3xl shadow-sm border border-gray-100"><i class="fas fa-ticket-alt text-5xl mb-4 text-gray-200 block"></i><p class="text-sm font-semibold text-gray-400">Belum ada tiket di sini.</p></div>`;
                    return;
                }

                myTickets.forEach(ticket => {
                    const event = STATE.db.events.find(e => e.ID === ticket.EventID);
                    if(!event) return;

                    const cat = STATE.db.categories.find(c => c.Name === event.Category);
                    const requiresForm = cat && cat.FormTemplateId !== '';
                    const hasFilledForm = STATE.db.formResponses.some(fr => fr.TicketID === ticket.ID);

                    let actionHtml = '';
                    if(status === 'active') {
                        actionHtml += `<div class="flex flex-col gap-2">`;
                        actionHtml += `<button onclick="CustomerController.showQR('${ticket.ID}', '${event.Title}')" class="px-4 py-2 bg-dark text-white rounded-xl text-[10px] font-bold shadow-soft hover:bg-gray-800 transition-colors"><i class="fas fa-qrcode mr-1"></i> QR Code</button>`;

                        if (requiresForm) {
                            if (hasFilledForm) {
                                actionHtml += `<span class="px-2 py-1.5 bg-green-50 text-secondary text-center rounded-lg text-[9px] font-extrabold uppercase tracking-wider"><i class="fas fa-check-circle"></i> Form Selesai</span>`;
                            } else {
                                actionHtml += `<button onclick="CustomerController.openFillForm('${ticket.ID}', '${event.ID}', '${cat.FormTemplateId}')" class="px-4 py-2 bg-primary text-white rounded-xl text-[10px] font-bold shadow-glow hover:bg-red-500 transition-colors animate-pulse"><i class="fas fa-clipboard-list mr-1"></i> Isi Form</button>`;
                            }
                        }
                        actionHtml += `</div>`;
                    } else {
                        actionHtml += `<div class="flex flex-col gap-2">`;
                        actionHtml += `<button onclick="CustomerController.viewGallery('${event.ID}', '${event.Title}')" class="px-3.5 py-2 bg-blue-50 text-tertiary font-bold text-[10px] rounded-xl flex items-center justify-center gap-1.5"><i class="fas fa-image"></i> Galeri</button>`;

                        const myReview = STATE.db.reviews.find(r => r.EventID === event.ID);
                        if (!myReview) {
                            actionHtml += `<button onclick="CustomerController.openReview('${event.ID}', '${event.Title}')" class="px-3.5 py-2 bg-primary/10 text-primary font-bold text-[10px] rounded-xl flex items-center justify-center gap-1.5"><i class="fas fa-star"></i> Ulas</button>`;
                        } else {
                            actionHtml += `<button onclick="CustomerController.openReview('${event.ID}', '${event.Title}')" class="px-3.5 py-2 bg-yellow-50 text-yellow-600 font-bold text-[10px] rounded-xl flex items-center justify-center gap-1.5 border border-yellow-100"><i class="fas fa-star"></i> Ulasan Saya</button>`;
                        }
                        actionHtml += `</div>`;
                    }

                    const dateD = new Date(event.Date);
                    const html = `
                        <div class="bg-white rounded-3xl shadow-soft border-l-4 ${status === 'active' ? 'border-l-primary' : 'border-l-gray-300'} p-5 flex items-center justify-between">
                            <div class="w-2/3 pr-2">
                                <span class="text-[9px] font-extrabold ${status === 'active' ? 'text-primary bg-red-50' : 'text-gray-500 bg-gray-100'} px-2 py-1 rounded-md uppercase tracking-widest mb-2 inline-block">${status === 'active' ? 'Tiket Aktif' : 'Telah Hadir'}</span>
                                <h4 class="font-extrabold text-dark text-sm leading-tight mb-1.5 truncate">${event.Title}</h4>
                                <p class="text-[10px] text-gray-500 font-semibold truncate"><i class="far fa-clock mr-1"></i> ${dateD.toLocaleDateString('id-ID',{day:'numeric',month:'short'})}</p>
                            </div>
                            <div class="shrink-0 flex items-center">${actionHtml}</div>
                        </div>
                    `;
                    container.innerHTML += html;
                });
            } catch (e) { console.error('Render Tickets Error', e); }
        },
        showQR(ticketId, eventTitle) {
            document.getElementById('qr-ticket-id').innerText = ticketId;
            document.getElementById('qr-event-title').innerText = eventTitle;
            document.getElementById('qr-image').src = `https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=${ticketId}&bgcolor=ffffff&color=2F3542&margin=1`;
            UIHelper.openModal('modal-ticket-qr');
        },
        openFillForm(ticketId, eventId, templateId) {
            const template = STATE.db.formTemplates.find(t => t.ID === templateId);
            if(!template) return UIHelper.showToast('Template form tidak ditemukan', 'error');

            document.getElementById('fill-form-ticket-id').value = ticketId;
            document.getElementById('fill-form-event-id').value = eventId;
            document.getElementById('fill-form-desc').innerText = `Silakan isi ${template.Title} sebagai persyaratan.`;

            const container = document.getElementById('dynamic-form-fields-container');
            container.innerHTML = template.fields.map((f, i) => {
                let inputHtml = '';
                if(f.type === 'dropdown') {
                    const opts = f.options.split(',').map(o => o.trim()).filter(o => o);
                    inputHtml = `<select name="field_${i}" class="input-modern form-response-input" data-label="${f.label}" required>
                                    <option value="">-- Pilih --</option>
                                    ${opts.map(o => `<option value="${o}">${o}</option>`).join('')}
                                 </select>`;
                } else {
                    inputHtml = `<input type="text" name="field_${i}" class="input-modern form-response-input" data-label="${f.label}" required>`;
                }

                return `
                    <div class="bg-white p-4 rounded-2xl border border-gray-100">
                        <label class="label-modern">${f.label} <span class="text-primary">*</span></label>
                        ${inputHtml}
                    </div>
                `;
            }).join('');

            UIHelper.openModal('modal-fill-form');
        },
        async submitFormEvent() {
            try {
                const ticketId = document.getElementById('fill-form-ticket-id').value;
                const eventId = document.getElementById('fill-form-event-id').value;
                const inputs = document.querySelectorAll('.form-response-input');

                let data = {};
                inputs.forEach(input => { data[input.dataset.label] = input.value; });

                await ApiService.call('SUBMIT_FORM_RESPONSE', { ticketId, eventId, customerPhone: STATE.currentUser.Phone, data });

                await ApiService.syncSession();
                UIHelper.closeModal(null, 'modal-fill-form', true);
                UIHelper.showToast('Data form berhasil dikirim!');
                this.renderTickets('active');
            } catch (e) { UIHelper.showToast(e.message, 'error'); }
        },
        viewGallery(eventId, title) {
            STATE.activeGalleryEventId = eventId;
            document.getElementById('gallery-view-event-title').innerText = title;
            const attended = STATE.db.tickets.some(t => t.EventID === eventId && t.Status === 'attended');
            document.getElementById('customer-gallery-upload-section').style.display = attended ? 'flex' : 'none';
            document.getElementById('cust-upload-event-photo').value = '';
            this.renderCustomerGallery();
            UIHelper.openModal('modal-view-gallery');
        },
        renderCustomerGallery() {
            const pics = STATE.db.galleries.filter(g => g.EventID === STATE.activeGalleryEventId);
            const grid = document.getElementById('gallery-grid');
            grid.innerHTML = pics.length ? pics.map((pic, i) => {
                const isMine = pic.Uploader === STATE.currentUser.Phone;
                const deleteBtn = isMine ? `<button onclick="CustomerController.deleteEventPhoto('${pic.Url}')" class="absolute top-2 right-2 w-7 h-7 bg-red-500/90 text-white rounded-full flex items-center justify-center shadow-md hover:scale-110 transition-transform"><i class="fas fa-trash text-xs"></i></button>` : '';
                return `<div class="aspect-square bg-gray-100 rounded-2xl overflow-hidden shadow-sm relative group"><img src="${pic.Url}" class="w-full h-full object-cover">${deleteBtn}</div>`;
            }).join('') : '<p class="text-xs col-span-2 text-center py-5 text-gray-400 font-semibold">Galeri belum tersedia untuk event ini.</p>';
        },
        async uploadEventPhoto(event) {
            const file = event.target.files[0];
            if (!file) return;
            UIHelper.showToast('Upload foto sedang dalam pengembangan', 'info');
        },
        deleteEventPhoto(url) {
            UIHelper.showToast('Penghapusan foto sedang dalam pengembangan', 'info');
        },
        openReview(eventId, title) {
            document.getElementById('review-event-id').value = eventId;
            document.getElementById('review-event-title').innerText = title;
            const existingReview = STATE.db.reviews.find(r => r.EventID === eventId);
            if (existingReview) {
                document.getElementById('review-modal-title').innerText = 'Ubah Penilaian Event';
                this.setRating(existingReview.Rating);
                document.getElementById('review-text').value = existingReview.Comment;
                document.getElementById('btn-delete-review').classList.remove('hidden');
                document.getElementById('btn-submit-review').innerText = 'Update Ulasan';
            } else {
                document.getElementById('review-modal-title').innerText = 'Penilaian Event';
                this.setRating(0);
                document.getElementById('review-text').value = '';
                document.getElementById('btn-delete-review').classList.add('hidden');
                document.getElementById('btn-submit-review').innerText = 'Kirim Ulasan';
            }
            UIHelper.openModal('modal-review');
        },
        setRating(val) {
            document.getElementById('review-rating-val').value = val;
            document.querySelectorAll('.star-rating i').forEach(star => {
                parseInt(star.dataset.val) <= val ? star.classList.add('active') : star.classList.remove('active');
            });
        },
        async submitReview() {
            try {
                const eventId = document.getElementById('review-event-id').value;
                const rating = parseInt(document.getElementById('review-rating-val').value);
                const text = document.getElementById('review-text').value.trim();

                if (rating < 1 || rating > 5) throw new Error("Rating harus antara 1-5");
                if (!text) throw new Error("Ulasan tidak boleh kosong");

                await ApiService.call('SUBMIT_REVIEW', {
                    eventId, customerPhone: STATE.currentUser.Phone,
                    customerName: STATE.currentUser.Name, rating, comment: text
                });

                await ApiService.syncSession();
                UIHelper.closeModal(null, 'modal-review', true);
                UIHelper.showToast("Ulasan tersimpan");
                this.renderTickets('attended');
            } catch (err) { UIHelper.showToast(err.message, "error"); }
        },
        deleteReview() {
            UIHelper.showConfirm("Hapus Ulasan", "Anda yakin ingin menghapus ulasan ini?", async () => {
                const eventId = document.getElementById('review-event-id').value;
                await ApiService.call('DELETE_REVIEW', { eventId, customerPhone: STATE.currentUser.Phone });
                await ApiService.syncSession();
                UIHelper.closeModal(null, 'modal-review', true);
                UIHelper.showToast("Ulasan dihapus");
                this.renderTickets('attended');
            });
        }
    };

    /**
     * @module AdminController
     */
    const AdminController = {
        init() {
            this.renderStats();
            this.renderEvents();
            this.renderOrders();
            const setRem = STATE.db.settings.find(s=>s.Key==='waReminder');
            const setThx = STATE.db.settings.find(s=>s.Key==='waThankYou');
            if(setRem) document.getElementById('wa-script-active').value = setRem.Value;
            if(setThx) document.getElementById('wa-script-attended').value = setThx.Value;
        },
        renderStats() {
            const pending = STATE.db.orders.filter(o => o.Status === 'pending').length;
            const active = STATE.db.tickets.filter(t => t.Status === 'active').length;
            const attended = STATE.db.tickets.filter(t => t.Status === 'attended').length;

            const badge = document.getElementById('admin-badge-orders');
            badge.innerText = pending;
            badge.style.display = pending === 0 ? 'none' : 'flex';
            if(pending>0) badge.classList.add('animate-pulse'); else badge.classList.remove('animate-pulse');

            document.getElementById('admin-stats').innerHTML = `
                <div class="glass-card rounded-3xl p-5 relative overflow-hidden bg-white/10 border border-white/20 backdrop-blur">
                    <div class="absolute -right-4 -bottom-4 opacity-20"><i class="fas fa-ticket-alt text-5xl text-white"></i></div>
                    <p class="text-[9px] text-gray-200 font-bold mb-1 uppercase tracking-widest relative z-10">Tiket (Aktif/Hadir)</p>
                    <p class="text-3xl font-extrabold text-white relative z-10">${active} <span class="text-base font-semibold text-gray-400">/ ${attended}</span></p>
                </div>
                <div class="glass-card rounded-3xl p-5 relative overflow-hidden bg-white/10 border border-white/20 backdrop-blur">
                    <div class="absolute -right-4 -bottom-4 opacity-20"><i class="fas fa-clock text-5xl text-primary"></i></div>
                    <p class="text-[9px] text-gray-200 font-bold mb-1 uppercase tracking-widest relative z-10">Order Tunda</p>
                    <p class="text-3xl font-extrabold text-primary relative z-10">${pending}</p>
                </div>
            `;
        },
        filterEvents() {
            const q = document.getElementById('search-admin-event').value.toLowerCase().trim();
            this.renderEvents(q);
        },
        renderEvents(query = '') {
            const container = document.getElementById('admin-event-list');
            const filtered = STATE.db.events.filter(e => String(e.Title).toLowerCase().includes(query) || String(e.Slug).toLowerCase().includes(query));

            container.innerHTML = filtered.map(event => `
                <div class="bg-white p-4 rounded-3xl shadow-sm border border-gray-100 flex flex-col gap-3">
                    <div class="flex items-center justify-between gap-4">
                        <div class="w-16 h-16 rounded-xl bg-gray-100 shrink-0 overflow-hidden shadow-inner relative">
                            <img src="${event.Banner}" class="w-full h-full object-cover" onerror="this.src='https://placehold.co/400x400/F1F2F6/2F3542?text=Img'">
                        </div>
                        <div class="flex-1 min-w-0">
                            <h4 class="font-extrabold text-dark text-sm truncate mb-0.5">${event.Title}</h4>
                            <p class="text-[9px] text-tertiary font-mono mb-1.5 truncate cursor-pointer hover:underline" onclick="UIHelper.copyToClipboard('https://activenation.id/e/${event.Slug}')">
                                /e/${event.Slug} <i class="fas fa-copy ml-1"></i>
                            </p>
                            <p class="text-[10px] text-gray-500 font-semibold truncate"><i class="fas fa-calendar-alt mr-1"></i> ${new Date(event.Date).toLocaleDateString('id-ID')} | ${event.Instructor}</p>
                        </div>
                        <div class="flex gap-2 shrink-0">
                            <button onclick="AdminController.editEvent('${event.ID}')" class="w-8 h-8 rounded-xl bg-blue-50 text-tertiary flex items-center justify-center hover:bg-blue-100 transition-colors"><i class="fas fa-pen text-xs"></i></button>
                            <button onclick="AdminController.deleteEvent('${event.ID}')" class="w-8 h-8 rounded-xl bg-red-50 text-primary flex items-center justify-center hover:bg-red-100 transition-colors"><i class="fas fa-trash text-xs"></i></button>
                        </div>
                    </div>
                    <div class="flex gap-2 w-full pt-2 border-t border-gray-50">
                        <button onclick="AdminController.openAttendanceReport('${event.ID}', '${event.Title}')" class="flex-1 h-9 rounded-xl bg-green-50 text-secondary text-[10px] font-extrabold hover:bg-green-100 transition-colors uppercase tracking-widest flex justify-center items-center gap-1.5"><i class="fas fa-chart-bar"></i> Laporan</button>
                        <button onclick="AdminController.openGalleryManager('${event.ID}', '${event.Title}')" class="flex-1 h-9 rounded-xl bg-gray-100 text-gray-600 text-[10px] font-extrabold hover:bg-gray-200 transition-colors uppercase tracking-widest flex justify-center items-center gap-1.5"><i class="fas fa-image"></i> Galeri</button>
                    </div>
                </div>
            `).join('') || '<p class="text-center text-sm font-semibold text-gray-400 py-4">Tidak ada event.</p>';
        },
        populateInstructors() {
            const sel = document.getElementById('crud-instructor');
            const insList = STATE.db.users.filter(u => u.Role === 'instructor');
            sel.innerHTML = insList.map(ins => `<option value="${ins.Name}">${ins.Name}</option>`).join('');
        },
        populateCategories() {
            const sel = document.getElementById('crud-category');
            sel.innerHTML = STATE.db.categories.map(c => `<option value="${c.Name}">${c.Name}</option>`).join('');
        },
        generateSlug() {
            const title = document.getElementById('crud-title').value;
            if(!document.getElementById('crud-id').value) {
                document.getElementById('crud-slug').value = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)+/g, '');
            }
        },
        openEventForm() {
            document.getElementById('event-crud-form').reset();
            document.getElementById('form-event-title').innerText = 'Buat Event Baru';
            document.getElementById('crud-id').value = '';
            this.populateInstructors();
            this.populateCategories();
            UIHelper.openModal('modal-event-form');
        },
        editEvent(id) {
            const e = STATE.db.events.find(ev => ev.ID === id);
            if(!e) return;
            this.populateInstructors();
            this.populateCategories();
            document.getElementById('form-event-title').innerText = 'Edit Event';
            document.getElementById('crud-id').value = e.ID;

            const mapping = {
                title: 'Title', slug: 'Slug', desc: 'Desc', banner: 'Banner', category: 'Category',
                city: 'City', price: 'Price', instructor: 'Instructor', instructorInfo: 'InstructorInfo',
                capacity: 'Capacity', venue: 'Venue', address: 'Address', gmaps: 'Gmaps', visibility: 'Visibility'
            };

            for(const [formKey, dbKey] of Object.entries(mapping)) {
                const el = document.getElementById(`crud-${formKey}`);
                if (el) el.value = e[dbKey] !== undefined ? e[dbKey] : '';
            }
            if (e.Date) {
                try { document.getElementById('crud-date').value = new Date(e.Date).toISOString().slice(0,16); } catch(err){}
            }

            UIHelper.openModal('modal-event-form');
        },
        async saveEvent() {
            try {
                const id = document.getElementById('crud-id').value;
                const capacity = parseInt(document.getElementById('crud-capacity').value);
                const price = parseInt(document.getElementById('crud-price').value);
                if (capacity < 1) throw new Error('Kapasitas minimal 1');
                if (price < 0) throw new Error('Harga tidak boleh negatif');

                const payload = {
                    id: id ? id : null,
                    title: document.getElementById('crud-title').value.trim(),
                    slug: document.getElementById('crud-slug').value.trim(),
                    banner: document.getElementById('crud-banner').value.trim(),
                    desc: document.getElementById('crud-desc').value.trim(),
                    category: document.getElementById('crud-category').value,
                    city: document.getElementById('crud-city').value.trim(),
                    date: document.getElementById('crud-date').value,
                    price: price,
                    instructor: document.getElementById('crud-instructor').value,
                    instructorInfo: document.getElementById('crud-instructorInfo').value.trim(),
                    capacity: capacity,
                    venue: document.getElementById('crud-venue').value.trim(),
                    address: document.getElementById('crud-address').value.trim(),
                    gmaps: document.getElementById('crud-gmaps').value.trim(),
                    visibility: document.getElementById('crud-visibility').value
                };

                const res = await ApiService.call('SAVE_EVENT', payload);
                await ApiService.initData();

                UIHelper.closeModal(null, 'modal-event-form', true);
                UIHelper.showToast(res.message);
                this.renderEvents();
            } catch(err) { UIHelper.showToast(err.message, 'error'); }
        },
        deleteEvent(id) {
            UIHelper.showConfirm("Hapus Event", "Anda yakin menghapus event ini beserta datanya?", async () => {
                try {
                    const res = await ApiService.call('DELETE_EVENT', { id });
                    await ApiService.initData();
                    UIHelper.showToast(res.message);
                    this.renderEvents(); this.renderStats();
                } catch(e) { UIHelper.showToast(e.message, 'error'); }
            });
        },

        // --- Categories Management ---
        openManageCategories() {
            this.resetCategoryForm();
            this.renderCategories();
            UIHelper.openModal('modal-manage-categories');
        },
        renderCategories() {
            const list = document.getElementById('category-list');
            list.innerHTML = STATE.db.categories.map((c, i) => {
                const ft = STATE.db.formTemplates.find(f => f.ID === c.FormTemplateId);
                return `
                <div class="flex items-center justify-between bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
                    <div>
                        <span class="text-sm font-bold text-dark block">${c.Name}</span>
                        <span class="text-[9px] bg-gray-100 text-gray-500 font-bold px-1.5 py-0.5 rounded uppercase mt-1 inline-block"><i class="fas fa-file-alt"></i> Form: ${ft ? ft.Title : 'Tidak Ada'}</span>
                    </div>
                    <div class="flex gap-2 shrink-0">
                        <button type="button" onclick="AdminController.editCategory('${c.ID}')" class="w-8 h-8 rounded-lg text-tertiary bg-blue-50 hover:bg-blue-100 transition-colors"><i class="fas fa-pen text-xs"></i></button>
                        <button type="button" onclick="AdminController.deleteCategory('${c.ID}')" class="w-8 h-8 rounded-lg text-primary bg-red-50 hover:bg-red-100 transition-colors"><i class="fas fa-trash text-xs"></i></button>
                    </div>
                </div>
            `}).join('');
        },
        resetCategoryForm() {
            document.getElementById('edit-category-id').value = '';
            document.getElementById('new-category-name').value = '';

            const sel = document.getElementById('new-category-form-template');
            sel.innerHTML = `<option value="">-- Tanpa Form Event --</option>` +
                            STATE.db.formTemplates.map(f => `<option value="${f.ID}">${f.Title}</option>`).join('');

            document.getElementById('category-form-title').innerText = 'Tambah Kategori';
            document.getElementById('btn-save-category').innerText = 'Tambah Kategori';
            document.getElementById('btn-cancel-edit-category').classList.add('hidden');
        },
        editCategory(id) {
            const c = STATE.db.categories.find(x => x.ID === id);
            if(!c) return;
            this.resetCategoryForm();
            document.getElementById('edit-category-id').value = c.ID;
            document.getElementById('new-category-name').value = c.Name;
            document.getElementById('new-category-form-template').value = c.FormTemplateId;
            document.getElementById('category-form-title').innerText = 'Edit Kategori';
            document.getElementById('btn-save-category').innerText = 'Simpan Perubahan';
            document.getElementById('btn-cancel-edit-category').classList.remove('hidden');
        },
        async saveCategory() {
            try {
                const id = document.getElementById('edit-category-id').value;
                const name = document.getElementById('new-category-name').value.trim();
                const formTemplateId = document.getElementById('new-category-form-template').value;

                if(!name) return UIHelper.showToast('Nama kategori wajib', 'error');

                await ApiService.call('SAVE_CATEGORY', { id: id||null, name, formTemplateId });
                await ApiService.initData();
                this.resetCategoryForm();
                this.renderCategories();
                UIHelper.showToast('Kategori disimpan');
            } catch(e) { UIHelper.showToast(e.message, 'error'); }
        },
        deleteCategory(id) {
            UIHelper.showConfirm("Hapus Kategori", "Yakin hapus kategori ini?", async () => {
                await ApiService.call('DELETE_CATEGORY', { id });
                await ApiService.initData();
                this.renderCategories();
                UIHelper.showToast('Kategori dihapus');
            });
        },

        // --- Form Templates Management ---
        openManageFormTemplates() {
            document.getElementById('form-template-list-view').classList.remove('hidden');
            document.getElementById('form-template-builder-view').classList.add('hidden');
            this.renderFormTemplates();
            UIHelper.openModal('modal-manage-form-templates');
        },
        renderFormTemplates() {
            const list = document.getElementById('form-template-list');
            list.innerHTML = STATE.db.formTemplates.map((ft, i) => `
                <div class="bg-white p-4 rounded-3xl shadow-sm border border-gray-100 flex flex-col gap-2">
                    <div class="flex justify-between items-start">
                        <div>
                            <span class="text-sm font-extrabold text-dark block mb-1">${ft.Title}</span>
                            <span class="text-[10px] text-gray-500 font-semibold">${ft.fields.length} Field Pertanyaan</span>
                        </div>
                        <div class="flex gap-2">
                            <button type="button" onclick="AdminController.editFormTemplate('${ft.ID}')" class="w-8 h-8 rounded-lg text-tertiary bg-blue-50 hover:bg-blue-100 transition-colors"><i class="fas fa-pen text-xs"></i></button>
                            <button type="button" onclick="AdminController.deleteFormTemplate('${ft.ID}')" class="w-8 h-8 rounded-lg text-primary bg-red-50 hover:bg-red-100 transition-colors"><i class="fas fa-trash text-xs"></i></button>
                        </div>
                    </div>
                </div>
            `).join('') || '<p class="text-xs text-center text-gray-400 py-4">Belum ada template form.</p>';
        },
        openFormTemplateBuilder() {
            document.getElementById('form-template-list-view').classList.add('hidden');
            document.getElementById('form-template-builder-view').classList.remove('hidden');
            document.getElementById('edit-form-template-id').value = '';
            document.getElementById('form-template-title').value = '';
            STATE.formBuilderFields = [];
            this.renderBuilderFields();
        },
        cancelFormTemplateBuilder() {
            document.getElementById('form-template-list-view').classList.remove('hidden');
            document.getElementById('form-template-builder-view').classList.add('hidden');
        },
        editFormTemplate(id) {
            const ft = STATE.db.formTemplates.find(f => f.ID === id);
            if(!ft) return;
            document.getElementById('form-template-list-view').classList.add('hidden');
            document.getElementById('form-template-builder-view').classList.remove('hidden');
            document.getElementById('edit-form-template-id').value = ft.ID;
            document.getElementById('form-template-title').value = ft.Title;
            STATE.formBuilderFields = JSON.parse(JSON.stringify(ft.fields));
            this.renderBuilderFields();
        },
        addFormField() {
            STATE.formBuilderFields.push({ label: '', type: 'text', options: '' });
            this.renderBuilderFields();
        },
        removeFormField(idx) {
            STATE.formBuilderFields.splice(idx, 1);
            this.renderBuilderFields();
        },
        updateFormField(idx, key, value) {
            STATE.formBuilderFields[idx][key] = value;
            if(key === 'type') this.renderBuilderFields();
        },
        renderBuilderFields() {
            const container = document.getElementById('form-template-fields-container');
            container.innerHTML = STATE.formBuilderFields.map((f, i) => `
                <div class="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 relative pt-8">
                    <button type="button" onclick="AdminController.removeFormField(${i})" class="absolute top-2 right-2 text-primary bg-red-50 w-6 h-6 rounded flex items-center justify-center hover:bg-red-100"><i class="fas fa-times text-xs"></i></button>
                    <span class="absolute top-3 left-4 text-[9px] font-bold text-gray-400">FIELD ${i+1}</span>
                    <div class="space-y-2">
                        <input type="text" class="input-modern bg-gray-50 text-xs py-2" placeholder="Label Pertanyaan (Misal: Golongan Darah)" value="${f.label}" onchange="AdminController.updateFormField(${i}, 'label', this.value)" required="required">
                        <select class="input-modern bg-gray-50 text-xs py-2" onchange="AdminController.updateFormField(${i}, 'type', this.value)">
                            <option value="text" ${f.type==='text'?'selected':''}>Teks Jawaban Singkat</option>
                            <option value="dropdown" ${f.type==='dropdown'?'selected':''}>Dropdown Pilihan</option>
                        </select>
                        ${f.type === 'dropdown' ? `
                            <input type="text" class="input-modern bg-gray-50 text-xs py-2" placeholder="Opsi pisahkan dengan koma (A, B, O, AB)" value="${f.options}" onchange="AdminController.updateFormField(${i}, 'options', this.value)" required="required">
                        ` : ''}
                    </div>
                </div>
            `).join('') || '<p class="text-[10px] text-center text-gray-400 border border-dashed border-gray-200 p-4 rounded-xl">Belum ada field, klik Tambah Field.</p>';
        },
        async saveFormTemplate() {
            try {
                const id = document.getElementById('edit-form-template-id').value;
                const title = document.getElementById('form-template-title').value.trim();

                if(!title || STATE.formBuilderFields.length === 0) return UIHelper.showToast('Judul dan minimal 1 field wajib diisi', 'error');

                for(let f of STATE.formBuilderFields) {
                    if(!f.label) return UIHelper.showToast('Label pertanyaan wajib diisi', 'error');
                    if(f.type === 'dropdown' && !f.options) return UIHelper.showToast('Opsi dropdown wajib diisi', 'error');
                }

                await ApiService.call('SAVE_FORM_TEMPLATE', { id: id||null, title, fields: STATE.formBuilderFields });
                await ApiService.initData();
                this.cancelFormTemplateBuilder();
                this.renderFormTemplates();
                UIHelper.showToast('Template disimpan');
            } catch(e) { UIHelper.showToast(e.message, 'error'); }
        },
        deleteFormTemplate(id) {
            UIHelper.showConfirm("Hapus Template", "Yakin hapus template form ini?", async () => {
                await ApiService.call('DELETE_FORM_TEMPLATE', { id });
                await ApiService.initData();
                this.renderFormTemplates();
                UIHelper.showToast('Template dihapus');
            });
        },

        // --- Attendance & Form Reports ---
        openAttendanceReport(eventId, title) {
            STATE.activeReportEventId = eventId;
            document.getElementById('report-event-title-admin').innerText = title;
            this.renderAttendanceList('active');
            UIHelper.openModal('modal-attendance-report');
        },
        renderAttendanceList(status) {
            const actCls = 'flex-1 py-2.5 bg-white rounded-xl font-bold text-xs shadow-sm text-primary transition-all';
            const inactCls = 'flex-1 py-2.5 text-gray-500 font-bold text-xs transition-all bg-transparent hover:bg-white/50 rounded-xl';
            document.getElementById('tab-report-active').className = status === 'active' ? actCls : inactCls;
            document.getElementById('tab-report-attended').className = status === 'attended' ? actCls : inactCls;
            document.getElementById('tab-report-forms').className = inactCls;

            const list = document.getElementById('admin-attendance-list');
            const tickets = STATE.db.tickets.filter(t => t.EventID === STATE.activeReportEventId && t.Status === status);

            list.innerHTML = tickets.map(t => {
                const user = STATE.db.users.find(u => u.Phone === t.CustomerPhone);
                return `
                <div class="flex items-center justify-between bg-white p-4 rounded-2xl border border-gray-100 shadow-sm">
                    <div>
                        <span class="text-sm font-extrabold text-dark block mb-0.5">${user ? user.Name : 'Unknown'}</span>
                        <div class="flex items-center gap-2">
                            <span class="text-[9px] bg-gray-100 text-gray-600 px-1.5 py-0.5 rounded font-mono">${t.ID}</span>
                            <span class="text-[9px] text-gray-400 font-medium">${t.CustomerPhone}</span>
                        </div>
                    </div>
                    <button onclick="AdminController.sendWaMessage('${t.ID}', '${status}')" class="shrink-0 h-9 px-4 rounded-xl bg-green-50 text-secondary border border-green-100 hover:bg-green-100 transition-colors font-bold text-[10px] uppercase tracking-widest flex gap-1.5 items-center">
                        <i class="fab fa-whatsapp text-sm"></i> Kirim
                    </button>
                </div>
            `}).join('') || `<p class="text-center text-xs text-gray-400 py-6">Tidak ada data peserta ${status === 'active' ? 'aktif' : 'hadir'}.</p>`;
        },
        renderFormResponsesList() {
            const actCls = 'flex-1 py-2.5 bg-white rounded-xl font-bold text-xs shadow-sm text-primary transition-all';
            const inactCls = 'flex-1 py-2.5 text-gray-500 font-bold text-xs transition-all bg-transparent hover:bg-white/50 rounded-xl';
            document.getElementById('tab-report-active').className = inactCls;
            document.getElementById('tab-report-attended').className = inactCls;
            document.getElementById('tab-report-forms').className = actCls;

            const list = document.getElementById('admin-attendance-list');
            const responses = STATE.db.formResponses.filter(fr => fr.EventID === STATE.activeReportEventId);

            list.innerHTML = responses.map(fr => {
                const user = STATE.db.users.find(u => u.Phone === fr.CustomerPhone);
                return `
                <div class="flex items-center justify-between bg-white p-4 rounded-2xl border border-gray-100 shadow-sm">
                    <div>
                        <span class="text-sm font-extrabold text-dark block mb-0.5">${user ? user.Name : 'Unknown'}</span>
                        <span class="text-[9px] text-gray-400 font-medium">Tiket: ${fr.TicketID}</span>
                    </div>
                    <button onclick="AdminController.viewFormResponse('${fr.ID}')" class="shrink-0 h-9 px-4 rounded-xl bg-blue-50 text-tertiary border border-blue-100 hover:bg-blue-100 transition-colors font-bold text-[10px] uppercase tracking-widest flex gap-1.5 items-center">
                        <i class="fas fa-eye text-sm"></i> Lihat Data
                    </button>
                </div>
            `}).join('') || `<p class="text-center text-xs text-gray-400 py-6">Belum ada peserta yang mengisi form untuk event ini.</p>`;
        },
        viewFormResponse(respId) {
            const fr = STATE.db.formResponses.find(r => r.ID === respId);
            if(!fr) return;
            const user = STATE.db.users.find(u => u.Phone === fr.CustomerPhone);

            document.getElementById('view-form-resp-name').innerText = user ? user.Name : 'Unknown';

            const content = document.getElementById('view-form-resp-content');
            let dataParsed = {};
            try { dataParsed = JSON.parse(fr.DataJSON); } catch(e){}

            content.innerHTML = Object.entries(dataParsed).map(([key, val]) => `
                <div class="bg-light p-3 rounded-xl border border-gray-100">
                    <p class="text-[9px] text-gray-400 font-bold uppercase tracking-widest mb-1">${key}</p>
                    <p class="text-sm font-extrabold text-dark">${val}</p>
                </div>
            `).join('');

            UIHelper.openModal('modal-view-form-response');
        },
        sendWaMessage(ticketId, status) {
            const ticket = STATE.db.tickets.find(t => t.ID === ticketId);
            const event = STATE.db.events.find(e => e.ID === ticket.EventID);
            const user = STATE.db.users.find(u => u.Phone === ticket.CustomerPhone);
            if(!ticket || !event || !user) return;

            const setRem = STATE.db.settings.find(s=>s.Key==='waReminder');
            const setThx = STATE.db.settings.find(s=>s.Key==='waThankYou');
            const scriptTemplate = status === 'active' ? (setRem?setRem.Value:'') : (setThx?setThx.Value:'');

            const linkUrl = `https://activenation.id/e/${event.Slug}`;
            const formLinkUrl = `https://activenation.id/form/${ticket.ID}`;

            let msg = scriptTemplate
                .replace(/{name}/g, user.Name)
                .replace(/{event}/g, event.Title)
                .replace(/{link}/g, linkUrl)
                .replace(/{ticket_id}/g, ticket.ID)
                .replace(/{form_link}/g, formLinkUrl);

            const waPhone = UIHelper.formatPhone(user.Phone);
            window.open(`https://wa.me/${waPhone}?text=${encodeURIComponent(msg)}`, '_blank');
        },

        // --- Settings & Configurations ---
        async saveSettings() {
            try {
                const waReminder = document.getElementById('wa-script-active').value.trim();
                const waThankYou = document.getElementById('wa-script-attended').value.trim();
                if(!waReminder || !waThankYou) throw new Error('Script WA tidak boleh kosong');

                await ApiService.call('SAVE_SETTINGS', { waReminder, waThankYou });
                await ApiService.syncSession();
                UIHelper.showToast('Script Automasi WA tersimpan');
            } catch (err) { UIHelper.showToast(err.message, 'error'); }
        },

        // --- Payments Management (Transfer & QRIS) ---
        openManagePayments() {
            this.resetPaymentForm();
            this.renderPayments();
            UIHelper.openModal('modal-manage-payments');
        },
        renderPayments() {
            const list = document.getElementById('payment-list');
            list.innerHTML = STATE.db.payments.map((p, i) => `
                <div class="flex items-center justify-between bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
                    <div class="flex items-center gap-3">
                        <div class="w-10 h-10 rounded-lg bg-gray-50 border border-gray-100 flex items-center justify-center overflow-hidden">
                            ${p.Type === 'qris' ? `<img src="${p.QrUrl}" class="w-full h-full object-cover">` : `<i class="fas fa-university text-gray-400"></i>`}
                        </div>
                        <div>
                            <span class="text-sm font-bold text-dark block">${p.Name}</span>
                            <span class="text-[9px] bg-gray-100 text-gray-500 font-bold px-1.5 py-0.5 rounded uppercase mt-1 inline-block">${p.Type}</span>
                            ${p.IsActive ? `<span class="text-[9px] bg-green-50 text-secondary font-bold px-1.5 py-0.5 rounded uppercase mt-1 inline-block ml-1">AKTIF</span>` : `<button onclick="AdminController.setPaymentActive('${p.ID}')" class="text-[9px] bg-gray-200 text-gray-600 font-bold px-1.5 py-0.5 rounded uppercase hover:bg-gray-300 mt-1 inline-block ml-1 transition-colors">Set Aktif</button>`}
                        </div>
                    </div>
                    <div class="flex gap-2 shrink-0">
                        <button type="button" onclick="AdminController.editPayment('${p.ID}')" class="w-8 h-8 rounded-lg text-tertiary bg-blue-50 hover:bg-blue-100 transition-colors"><i class="fas fa-pen text-xs"></i></button>
                        <button type="button" onclick="AdminController.deletePayment('${p.ID}')" class="w-8 h-8 rounded-lg text-primary bg-red-50 hover:bg-red-100 transition-colors"><i class="fas fa-trash text-xs"></i></button>
                    </div>
                </div>
            `).join('') || '<p class="text-xs text-center text-gray-400 py-4">Belum ada metode pembayaran.</p>';
        },
        togglePaymentFields() {
            const type = document.getElementById('new-payment-type').value;
            if(type === 'qris') {
                document.getElementById('payment-transfer-fields').classList.add('hidden');
                document.getElementById('payment-qris-fields').classList.remove('hidden');
            } else {
                document.getElementById('payment-transfer-fields').classList.remove('hidden');
                document.getElementById('payment-qris-fields').classList.add('hidden');
            }
        },
        resetPaymentForm() {
            document.getElementById('edit-payment-id').value = '';
            document.getElementById('new-payment-type').value = 'transfer';
            document.getElementById('new-payment-name').value = '';
            document.getElementById('new-payment-acc-no').value = '';
            document.getElementById('new-payment-acc-name').value = '';
            document.getElementById('new-payment-qr-url').value = '';

            document.getElementById('payment-form-title').innerText = 'Tambah Metode Pembayaran';
            document.getElementById('btn-save-payment').innerText = 'Simpan Metode';
            document.getElementById('btn-cancel-edit-payment').classList.add('hidden');
            this.togglePaymentFields();
        },
        editPayment(id) {
            const p = STATE.db.payments.find(x => x.ID === id);
            if(!p) return;
            document.getElementById('edit-payment-id').value = p.ID;
            document.getElementById('new-payment-type').value = p.Type;
            document.getElementById('new-payment-name').value = p.Name;
            if(p.Type === 'transfer') {
                document.getElementById('new-payment-acc-no').value = p.AccountNo || '';
                document.getElementById('new-payment-acc-name').value = p.AccountName || '';
            } else {
                document.getElementById('new-payment-qr-url').value = p.QrUrl || '';
            }

            document.getElementById('payment-form-title').innerText = 'Edit Metode Pembayaran';
            document.getElementById('btn-save-payment').innerText = 'Simpan Perubahan';
            document.getElementById('btn-cancel-edit-payment').classList.remove('hidden');
            this.togglePaymentFields();
        },
        async setPaymentActive(id) {
            const p = STATE.db.payments.find(x => x.ID === id);
            if(!p) return;
            p.isActive = true;
            await ApiService.call('SAVE_PAYMENT', {
                id: p.ID, type: p.Type, name: p.Name, accountNo: p.AccountNo,
                accountName: p.AccountName, qrUrl: p.QrUrl, isActive: true
            });
            await ApiService.initData();
            this.renderPayments();
            UIHelper.showToast('Metode pembayaran diaktifkan');
        },
        async savePayment() {
            try {
                const id = document.getElementById('edit-payment-id').value;
                const type = document.getElementById('new-payment-type').value;
                const name = document.getElementById('new-payment-name').value.trim();
                const accountNo = document.getElementById('new-payment-acc-no').value.trim();
                const accountName = document.getElementById('new-payment-acc-name').value.trim();
                const qrUrl = document.getElementById('new-payment-qr-url').value.trim();

                if(!name) return UIHelper.showToast('Nama bank/ewallet wajib', 'error');
                let payload = { id: id||null, type, name, isActive: true };

                if(type === 'transfer') {
                    if(!accountNo || !accountName) return UIHelper.showToast('No rekening dan nama wajib diisi', 'error');
                    payload.accountNo = accountNo; payload.accountName = accountName;
                } else {
                    if(!qrUrl) return UIHelper.showToast('URL QRIS wajib diisi', 'error');
                    payload.qrUrl = qrUrl;
                }

                await ApiService.call('SAVE_PAYMENT', payload);
                await ApiService.initData();
                this.resetPaymentForm();
                this.renderPayments();
                UIHelper.showToast('Metode pembayaran disimpan');
            } catch(e) { UIHelper.showToast(e.message, 'error'); }
        },
        deletePayment(id) {
            UIHelper.showConfirm("Hapus Pembayaran", "Yakin hapus metode ini?", async () => {
                await ApiService.call('DELETE_PAYMENT', { id });
                await ApiService.initData();
                this.renderPayments();
                UIHelper.showToast('Metode pembayaran dihapus');
            });
        },

        // --- Other Admin Functions ---
        openGalleryManager(eventId, title) {
            STATE.activeGalleryEventId = eventId;
            document.getElementById('gallery-event-title-admin').innerText = title;
            this.renderAdminGallery();
            UIHelper.openModal('modal-manage-gallery');
        },
        renderAdminGallery() {
            const list = document.getElementById('admin-gallery-list');
            const pics = STATE.db.galleries.filter(g => g.EventID === STATE.activeGalleryEventId);
            list.innerHTML = pics.map((pic, i) => `
                <div class="flex items-center gap-3 bg-white p-3 rounded-2xl border border-gray-100 shadow-sm">
                    <img src="${pic.Url}" class="w-14 h-14 object-cover rounded-xl shadow-inner" onerror="this.src='https://placehold.co/400x400/F1F2F6/2F3542?text=Error'">
                    <div class="flex-1 min-w-0">
                        <input type="text" readonly="readonly" value="${pic.Url}" class="w-full bg-transparent text-xs text-gray-500 font-mono truncate outline-none mb-1">
                        <span class="text-[9px] bg-gray-100 text-gray-500 font-bold px-2 py-0.5 rounded-md uppercase">Oleh: ${pic.Uploader === 'admin' ? 'Admin' : pic.Uploader}</span>
                    </div>
                </div>
            `).join('') || '<p class="text-xs text-center text-gray-400 font-semibold py-6">Belum ada foto.</p>';
        },
        renderOrders() {
            const pending = STATE.db.orders.filter(o => o.Status === 'pending');
            const container = document.getElementById('admin-order-list');

            if(pending.length === 0) {
                container.innerHTML = `<div class="text-center p-8 bg-white rounded-3xl shadow-sm border border-gray-100"><i class="fas fa-check-circle text-5xl text-gray-200 mb-3 block"></i><p class="text-xs text-gray-400 font-semibold">Semua pesanan sudah tervalidasi.</p></div>`;
                return;
            }

            container.innerHTML = pending.map(order => {
                const event = STATE.db.events.find(e => e.ID === order.EventID);
                const user = STATE.db.users.find(u => u.Phone === order.CustomerPhone);
                return `
                    <div class="bg-white p-5 rounded-3xl shadow-soft border-l-4 border-l-yellow-400 border border-gray-50 mb-4">
                        <div class="flex justify-between items-start mb-4">
                            <span class="text-[9px] bg-yellow-50 text-yellow-600 font-extrabold px-2.5 py-1 rounded-lg uppercase tracking-widest shadow-sm">Perlu Validasi</span>
                            <span class="text-[10px] text-gray-400 font-mono font-bold">${order.ID}</span>
                        </div>
                        <h4 class="font-extrabold text-base text-dark mb-1">${user ? user.Name : 'Unknown'}</h4>
                        <p class="text-xs text-gray-500 font-semibold">${event ? event.Title : 'Event Dihapus'} <span class="font-bold text-dark">(x${order.Qty})</span></p>
                        <p class="text-xl font-extrabold text-primary my-4">${UIHelper.formatRupiah(order.Price)}</p>

                        <div class="flex gap-2 mt-2">
                            <button type="button" class="px-3 py-3 bg-light text-dark text-xs font-bold rounded-xl hover:bg-gray-200 transition-colors" onclick="UIHelper.openModal('modal-view-image')"><i class="fas fa-image"></i> Bukti</button>
                            <button type="button" class="flex-1 py-3 bg-dark text-white text-xs font-bold rounded-xl shadow-soft hover:bg-gray-800 active:scale-95 transition-all" onclick="AdminController.resolveOrder('${order.ID}', true)"><i class="fas fa-check mr-1"></i> Terima</button>
                            <button type="button" class="px-4 py-3 bg-red-50 text-primary text-xs font-bold rounded-xl shadow-soft hover:bg-red-100 active:scale-95 transition-all" onclick="AdminController.resolveOrder('${order.ID}', false)"><i class="fas fa-times"></i></button>
                        </div>
                    </div>
                `;
            }).join('');
        },
        resolveOrder(id, isApproved) {
            let msg = isApproved ? "Konfirmasi dana sudah masuk dan tiket siap diaktifkan?" : "Tolak pesanan ini dan hapus dari daftar?";
            UIHelper.showConfirm("Validasi Pembayaran", msg, async () => {
                try {
                    const res = await ApiService.call('RESOLVE_ORDER', { orderId: id, isApproved });
                    await ApiService.syncSession();
                    UIHelper.showToast(res.message);
                    this.renderOrders();
                    this.renderStats();
                } catch(e) { UIHelper.showToast(e.message, 'error'); }
            });
        },
        simulateCameraScan() {
            const scanner = document.getElementById('scanner-beam');
            scanner.classList.remove('hidden');
            setTimeout(() => {
                scanner.classList.add('hidden');
                const tkt = STATE.db.tickets.find(t => t.Status === 'active');
                if(tkt) this.processScan(tkt.ID);
                else UIHelper.showToast("Simulasi gagal: Tidak ada tiket aktif.", "error");
            }, 2000);
        },
        submitManualScan() {
            const id = document.getElementById('manual-ticket-id').value.toUpperCase().trim();
            if(!id) return UIHelper.showToast('ID tidak boleh kosong', 'error');
            this.processScan(id);
            document.getElementById('manual-ticket-id').value = '';
        },
        async processScan(ticketId) {
            try {
                const res = await ApiService.call('SCAN_TICKET', { ticketId });
                await ApiService.syncSession();
                UIHelper.showToast(res.message, 'success');
                this.renderStats();
            } catch(e) { UIHelper.showToast(e.message, 'error'); }
        },

        // --- Instructor, Vouchers, Logs ---
        openManageInstructors() { this.resetInstructorForm(); this.renderInstructors(); UIHelper.openModal('modal-manage-instructors'); },
        renderInstructors() {
            const insList = STATE.db.users.filter(u => u.Role === 'instructor');
            document.getElementById('instructor-list').innerHTML = insList.map(ins => `
                <div class="flex justify-between items-center bg-white p-4 rounded-2xl border border-gray-100 shadow-sm">
                    <div>
                        <span class="text-sm font-extrabold text-dark block">${ins.Name}</span>
                        <span class="text-[10px] text-gray-500 font-mono">ID: ${ins.Phone}</span>
                    </div>
                    <div class="flex gap-2">
                        <button type="button" onclick="AdminController.editInstructor('${ins.Phone}')" class="text-tertiary w-8 h-8 bg-blue-50 rounded-xl hover:bg-blue-100 transition-colors"><i class="fas fa-pen text-xs"></i></button>
                        <button type="button" onclick="AdminController.deleteInstructor('${ins.Phone}')" class="text-primary w-8 h-8 bg-red-50 rounded-xl hover:bg-red-100 transition-colors"><i class="fas fa-trash text-xs"></i></button>
                    </div>
                </div>
            `).join('') || '<p class="text-xs text-center text-gray-400 py-4">Belum ada instruktur.</p>';
        },
        resetInstructorForm() {
            document.getElementById('edit-instructor-phone-old').value = '';
            document.getElementById('new-instructor-name').value = '';
            document.getElementById('new-instructor-phone').value = '';
            document.getElementById('new-instructor-pass').value = '';
            document.getElementById('new-instructor-pass').required = true;
            document.getElementById('instructor-form-title').innerText = 'Buat Akun Coach Baru';
            document.getElementById('btn-save-instructor').innerText = 'Buat Akun';
            document.getElementById('btn-cancel-edit-ins').classList.add('hidden');
        },
        editInstructor(phone) {
            const ins = STATE.db.users.find(u=>u.Phone === phone);
            if(!ins) return;
            document.getElementById('edit-instructor-phone-old').value = ins.Phone;
            document.getElementById('new-instructor-name').value = ins.Name;
            document.getElementById('new-instructor-phone').value = ins.Phone;
            document.getElementById('new-instructor-pass').value = '';
            document.getElementById('new-instructor-pass').required = false;
            document.getElementById('instructor-form-title').innerText = 'Edit Akun Instruktur';
            document.getElementById('btn-save-instructor').innerText = 'Simpan Perubahan';
            document.getElementById('btn-cancel-edit-ins').classList.remove('hidden');
        },
        async saveInstructor() {
            try {
                const oldPhone = document.getElementById('edit-instructor-phone-old').value;
                const name = document.getElementById('new-instructor-name').value.trim();
                const phone = document.getElementById('new-instructor-phone').value.trim();
                const pass = document.getElementById('new-instructor-pass').value;

                await ApiService.call('SAVE_INSTRUCTOR', { oldPhone, name, phone, pass });
                await ApiService.syncSession();
                UIHelper.showToast('Data Instruktur disimpan');
                this.resetInstructorForm(); this.renderInstructors();
            } catch (err) { UIHelper.showToast(err.message, 'error'); }
        },
        deleteInstructor(phone) {
            UIHelper.showConfirm("Hapus Instruktur", "Hapus akun instruktur ini?", async () => {
                try {
                    const name = STATE.db.users.find(u=>u.Phone===phone).Name;
                    const hasEvents = STATE.db.events.some(e => e.Instructor === name);
                    if(hasEvents) return UIHelper.showToast('Instruktur sedang memandu event aktif!', 'error');

                    await ApiService.call('DELETE_INSTRUCTOR', { phone });
                    await ApiService.syncSession();
                    this.renderInstructors();
                    UIHelper.showToast('Akun dihapus');
                } catch(e) { UIHelper.showToast(e.message, 'error'); }
            });
        },
        openManageVouchers() { this.resetVoucherForm(); this.renderVouchers(); UIHelper.openModal('modal-manage-vouchers'); },
        renderVouchers() {
            document.getElementById('voucher-list').innerHTML = STATE.db.vouchers.map((v, i) => `
                <div class="flex justify-between items-center bg-white p-4 rounded-2xl border border-gray-100 shadow-sm">
                    <div>
                        <span class="text-sm font-extrabold text-dark block mb-1">${v.Code}</span>
                        <span class="text-[10px] text-white bg-secondary px-2 py-0.5 rounded uppercase font-bold tracking-widest shadow-sm">Potongan: ${v.Type==='percent'?v.Val+'%':UIHelper.formatRupiah(v.Val)}</span>
                    </div>
                    <div class="flex gap-2">
                        <button type="button" onclick="AdminController.editVoucher('${v.ID}')" class="text-tertiary w-8 h-8 bg-blue-50 rounded-xl hover:bg-blue-100 transition-colors"><i class="fas fa-pen text-xs"></i></button>
                        <button type="button" onclick="AdminController.deleteVoucher('${v.ID}')" class="text-primary w-8 h-8 bg-red-50 rounded-xl hover:bg-red-100 transition-colors"><i class="fas fa-trash text-xs"></i></button>
                    </div>
                </div>
            `).join('');
        },
        resetVoucherForm() {
            document.getElementById('edit-voucher-id').value = '';
            document.getElementById('new-voucher-code').value = '';
            document.getElementById('new-voucher-val').value = '';
            document.getElementById('btn-save-voucher').innerText = 'Generate Voucher';
            document.getElementById('btn-cancel-edit-voucher').classList.add('hidden');
        },
        editVoucher(id) {
            const v = STATE.db.vouchers.find(x => x.ID === id);
            if(!v) return;
            document.getElementById('edit-voucher-id').value = v.ID;
            document.getElementById('new-voucher-code').value = v.Code;
            document.getElementById('new-voucher-type').value = v.Type;
            document.getElementById('new-voucher-val').value = v.Val;
            document.getElementById('btn-save-voucher').innerText = 'Simpan Perubahan';
            document.getElementById('btn-cancel-edit-voucher').classList.remove('hidden');
        },
        async saveVoucher() {
            try {
                const id = document.getElementById('edit-voucher-id').value;
                const code = document.getElementById('new-voucher-code').value.toUpperCase().trim();
                const type = document.getElementById('new-voucher-type').value;
                const val = parseInt(document.getElementById('new-voucher-val').value);

                await ApiService.call('SAVE_VOUCHER', { id: id||null, code, type, val });
                await ApiService.initData();
                this.resetVoucherForm(); this.renderVouchers();
                UIHelper.showToast('Voucher disimpan');
            } catch (err) { UIHelper.showToast(err.message, 'error'); }
        },
        deleteVoucher(id) {
            UIHelper.showConfirm("Hapus Voucher", "Yakin ingin menghapus voucher ini?", async () => {
                await ApiService.call('DELETE_VOUCHER', { id });
                await ApiService.initData();
                this.renderVouchers(); UIHelper.showToast('Voucher dihapus');
            });
        },
        openAuditLogs() {
            const list = document.getElementById('audit-log-list');
            list.innerHTML = STATE.db.auditLogs.map(l => `
                <div class="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 text-xs">
                    <div class="flex justify-between mb-2 items-center">
                        <span class="font-extrabold text-primary bg-red-50 px-2 py-1 rounded text-[9px] uppercase tracking-widest">${l.Action}</span>
                        <span class="text-gray-400 font-semibold text-[10px]">${l.Time}</span>
                    </div>
                    <p class="text-dark font-bold mb-1">${l.User} <span class="text-gray-400 font-normal">(${l.IP})</span></p>
                    <p class="text-gray-500 font-mono text-[10px] bg-light p-2 rounded-lg mt-2">${l.Detail}</p>
                </div>
            `).join('') || '<p class="text-center text-xs text-gray-400 py-6">Tidak ada log aktivitas.</p>';
            UIHelper.openModal('modal-audit-logs');
        }
    };

    /**
     * @module InstructorController
     */
    const InstructorController = {
        init() {
            const coachName = STATE.currentUser.Name;
            document.getElementById('instructor-name-display').innerText = coachName;
            const myEvents = STATE.db.events.filter(e => e.Instructor === coachName);

            let totalActive = 0, totalAttended = 0;
            const container = document.getElementById('ins-event-list');

            if(myEvents.length === 0) {
                container.innerHTML = '<div class="text-center p-8 bg-white rounded-3xl shadow-sm border border-gray-100"><p class="text-sm font-semibold text-gray-400">Belum ada jadwal kelas ditugaskan.</p></div>';
            } else {
                container.innerHTML = myEvents.map(e => {
                    const eActive = STATE.db.tickets.filter(t => t.EventID === e.ID && t.Status === 'active').length;
                    const eAttended = STATE.db.tickets.filter(t => t.EventID === e.ID && t.Status === 'attended').length;
                    totalActive += eActive; totalAttended += eAttended;
                    const d = new Date(e.Date);
                    return `
                        <div class="bg-white p-5 rounded-3xl shadow-soft border border-gray-50 flex items-center gap-4">
                            <div class="w-14 h-14 rounded-2xl bg-tertiary/10 flex flex-col justify-center items-center text-tertiary border border-tertiary/20 shadow-sm shrink-0">
                                <span class="text-lg font-extrabold leading-none">${d.getDate()}</span>
                                <span class="text-[9px] uppercase font-bold tracking-widest mt-0.5">${d.toLocaleString('id-ID',{month:'short'})}</span>
                            </div>
                            <div class="flex-1 min-w-0">
                                <h4 class="font-extrabold text-dark text-sm truncate mb-2">${e.Title}</h4>
                                <div class="w-full bg-light rounded-full h-2 mb-1.5 overflow-hidden"><div class="bg-gradient-to-r from-tertiary to-secondary h-2 rounded-full transition-all" style="width: ${eActive+eAttended===0?0:(eAttended/(eActive+eAttended))*100}%"></div></div>
                                <div class="flex justify-between">
                                    <p class="text-[10px] text-gray-400 font-bold">Terdaftar: ${eActive+eAttended}</p>
                                    <p class="text-[10px] text-secondary font-extrabold">Hadir: ${eAttended}</p>
                                </div>
                            </div>
                            <button onclick="CustomerController.viewGallery('${e.ID}', '${e.Title}')" class="w-10 h-10 bg-light text-dark rounded-xl flex items-center justify-center hover:bg-gray-200 active:scale-95 transition-all shrink-0"><i class="fas fa-image"></i></button>
                        </div>
                    `;
                }).join('');
            }

            document.getElementById('ins-dashboard-stats').innerHTML = `
                <div class="bg-dark rounded-[2rem] p-6 text-white shadow-xl relative overflow-hidden">
                    <div class="absolute -right-10 -top-10 w-40 h-40 bg-secondary rounded-full mix-blend-overlay filter blur-2xl opacity-40"></div>
                    <p class="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1 relative z-10">Rekap Kinerja</p>
                    <h2 class="text-2xl font-extrabold mb-6 relative z-10">${myEvents.length} <span class="text-sm font-normal text-gray-300">Kelas Dikelola</span></h2>

                    <div class="flex gap-4 relative z-10">
                        <div class="flex-1 bg-white/10 rounded-2xl p-4 border border-white/10 text-center backdrop-blur-sm">
                            <p class="text-[9px] text-tertiary font-bold uppercase tracking-widest mb-1">Peserta Aktif</p>
                            <p class="text-2xl font-extrabold">${totalActive}</p>
                        </div>
                        <div class="flex-1 bg-white/10 rounded-2xl p-4 border border-white/10 text-center backdrop-blur-sm">
                            <p class="text-[9px] text-secondary font-bold uppercase tracking-widest mb-1">Total Hadir</p>
                            <p class="text-2xl font-extrabold">${totalAttended}</p>
                        </div>
                    </div>
                </div>
            `;

            const rContainer = document.getElementById('ins-feedback-list');
            rContainer.innerHTML = STATE.db.reviews.length ? STATE.db.reviews.map(r => {
                const e = STATE.db.events.find(ev => ev.ID === r.EventID);
                return `
                    <div class="bg-white p-5 rounded-3xl shadow-soft border border-gray-50">
                        <div class="flex justify-between items-start mb-3">
                            <div class="flex items-center gap-3">
                                <div class="w-10 h-10 rounded-full bg-light text-dark flex items-center justify-center font-bold text-xs">${UIHelper.getInitials(r.CustomerName)}</div>
                                <div>
                                    <h4 class="font-extrabold text-sm text-dark">${r.CustomerName}</h4>
                                    <p class="text-[9px] text-primary font-bold uppercase tracking-widest truncate w-32">${e?e.Title:''}</p>
                                </div>
                            </div>
                            <div class="text-[10px] bg-yellow-50 px-2 py-1 rounded-lg">${Array(5).fill().map((_,i)=>`<i class="fas fa-star ${i<r.Rating?'text-yellow-400':'text-gray-200'}"></i>`).join('')}</div>
                        </div>
                        <p class="text-xs text-gray-600 font-medium leading-relaxed italic mt-2 bg-light p-3 rounded-xl">&quot;${r.Comment}&quot;</p>
                    </div>
                `;
            }).join('') : '<p class="text-sm font-semibold text-gray-400 text-center py-8">Belum ada ulasan peserta.</p>';
        }
    };

    /**
     * @module Bootstrap
     */
    window.onload = async () => {
        try {
            await ApiService.initData();
        } catch(e) {
            UIHelper.showToast('Gagal memuat data dari server. Periksa koneksi.', 'error');
        }
    };
//
